/**
 * Deterministic event-loop backtester.
 *
 * THE TWO RULES THAT DECIDE WHETHER A BACKTEST IS WORTH ANYTHING
 *
 * 1. NO LOOK-AHEAD. A signal produced from bar `i` is filled at bar `i+1`'s
 *    OPEN, never at bar i's close. Filling on the close of the bar that
 *    generated the signal assumes you saw the closing price before deciding —
 *    it is the single most common way a backtest invents returns that cannot be
 *    earned. Stops and targets are the one exception, and they are checked
 *    against bar i+1's own high/low because that is genuinely when they would
 *    have triggered.
 *
 * 2. COSTS ARE NOT OPTIONAL. Commission and slippage are applied to every fill.
 *    A strategy that only works at zero cost is not a strategy.
 *
 * The engine is deterministic: same bars, same strategy, same params produce
 * byte-identical results. No RNG, no clock.
 */

import { prepare, featuresAt } from "./features.js"

export const DEFAULT_CONFIG = {
  initialCash: 100000,
  // Fraction of equity committed per position.
  positionSize: 0.1,
  maxPositions: 5,
  // Per-share commission, as a US broker would charge.
  commissionPerShare: 0.005,
  minCommission: 1,
  // Slippage as a fraction of price, applied against you on entry and exit.
  slippagePct: 0.0005,
  allowShort: false,
}

let orderSeq = 0
function nextOrderId(prefix) {
  orderSeq += 1
  return `${prefix}-${orderSeq}`
}

/** Resets the order counter so a run is reproducible in isolation. */
export function resetOrderIds() {
  orderSeq = 0
}

function commission(shares, config) {
  return Math.max(config.minCommission, shares * config.commissionPerShare)
}

/**
 * Run one strategy over one symbol's bars.
 *
 * @param {object} args
 * @param {string} args.symbol
 * @param {Array}  args.bars       ascending OHLCV
 * @param {object} args.strategy   from strategy.js
 * @param {object} [args.params]   overrides for strategy.params
 * @param {object} [args.config]   overrides for DEFAULT_CONFIG
 * @param {number} [args.startIndex] first bar eligible to trade (warm-up)
 */
export function backtestSymbol({ symbol, bars, strategy, params, config, startIndex }) {
  const cfg = { ...DEFAULT_CONFIG, ...(config || {}) }
  const p = { ...strategy.params, ...(params || {}) }
  const ctxBase = { params: p, symbol }

  if (!Array.isArray(bars) || bars.length < 30) {
    return emptyResult(symbol, strategy, p, cfg)
  }

  const featureCtx = prepare(bars)
  // Indicators need a warm-up; trading before EMA50/RSI exist is trading on
  // nulls, which silently becomes "no signal" and biases the sample.
  const warmUp = Math.max(startIndex || 0, 50)

  let cash = cfg.initialCash
  let position = null
  const trades = []
  const equityCurve = []
  const orders = []
  let pendingEntry = null
  let pendingExit = null

  for (let i = warmUp; i < bars.length; i += 1) {
    const bar = bars[i]
    const f = featuresAt(featureCtx, i)

    /* ---- 1. Execute orders decided on the PREVIOUS bar, at this bar's open ---- */
    if (pendingExit && position) {
      const fillPrice = bar.open * (1 - cfg.slippagePct)
      const fee = commission(position.shares, cfg)
      const proceeds = position.shares * fillPrice - fee
      cash += proceeds
      trades.push(closeTrade(position, bar, fillPrice, fee, pendingExit.reason))
      orders.push({
        id: nextOrderId("exit"),
        symbol, side: "sell", shares: position.shares,
        price: fillPrice, time: bar.time, status: "filled",
        reason: pendingExit.reason, fee,
      })
      position = null
      pendingExit = null
    }

    if (pendingEntry && !position) {
      const fillPrice = bar.open * (1 + cfg.slippagePct)
      const budget = (cash + positionValue(position, bar)) * cfg.positionSize
      const shares = Math.floor(budget / fillPrice)
      if (shares > 0) {
        const fee = commission(shares, cfg)
        const cost = shares * fillPrice + fee
        if (cost <= cash) {
          cash -= cost
          position = {
            symbol,
            shares,
            entryPrice: fillPrice,
            entryTime: bar.time,
            entryIndex: i,
            barsHeld: 0,
            entryReason: pendingEntry.reason,
            entryFee: fee,
            stop: null,
            target: null,
            features: pendingEntry.features,
          }
          orders.push({
            id: nextOrderId("entry"),
            symbol, side: "buy", shares,
            price: fillPrice, time: bar.time, status: "filled",
            reason: pendingEntry.reason, fee,
          })
        }
      }
      pendingEntry = null
    }

    /* ---- 2. Manage an open position against THIS bar's range ---- */
    if (position) {
      position.barsHeld = i - position.entryIndex
      position.stop = strategy.stopPrice ? strategy.stopPrice(f, position, ctxBase) : null
      position.target = strategy.targetPrice ? strategy.targetPrice(f, position, ctxBase) : null

      // Stops and targets fill intrabar — that is genuinely when they trigger.
      // Checking the stop first is the conservative assumption when a bar spans
      // both levels and we cannot know which came first.
      let exitPrice = null
      let exitReason = null
      if (position.stop !== null && bar.low <= position.stop) {
        exitPrice = Math.min(position.stop, bar.open) * (1 - cfg.slippagePct)
        exitReason = "Stop hit"
      } else if (position.target !== null && bar.high >= position.target) {
        exitPrice = Math.max(position.target, bar.open) * (1 - cfg.slippagePct)
        exitReason = "Target hit"
      }

      if (exitPrice !== null) {
        const fee = commission(position.shares, cfg)
        cash += position.shares * exitPrice - fee
        trades.push(closeTrade(position, bar, exitPrice, fee, exitReason))
        orders.push({
          id: nextOrderId("exit"),
          symbol, side: "sell", shares: position.shares,
          price: exitPrice, time: bar.time, status: "filled",
          reason: exitReason, fee,
        })
        position = null
      }
    }

    /* ---- 3. Decide what to do NEXT bar, from features known now ---- */
    if (position && !pendingExit) {
      const wantExit = strategy.exit ? strategy.exit(f, position, ctxBase) : false
      if (wantExit) {
        pendingExit = { reason: wantExit.reason || "Exit rule" }
      }
    } else if (!position && !pendingEntry) {
      const wantEntry = strategy.entry ? strategy.entry(f, ctxBase) : false
      if (wantEntry) {
        pendingEntry = { reason: wantEntry.reason || "Entry rule", features: f }
      }
    }

    /* ---- 4. Mark to market ---- */
    const equity = cash + positionValue(position, bar)
    equityCurve.push({ time: bar.time, equity, cash, exposure: positionValue(position, bar) })
  }

  // Close anything still open at the final bar, so P&L is complete rather than
  // flattered by an unrealised winner.
  if (position) {
    const last = bars[bars.length - 1]
    const fillPrice = last.close * (1 - cfg.slippagePct)
    const fee = commission(position.shares, cfg)
    cash += position.shares * fillPrice - fee
    trades.push(closeTrade(position, last, fillPrice, fee, "Backtest ended"))
    position = null
  }

  return {
    symbol,
    strategy: { id: strategy.id, name: strategy.name },
    params: p,
    config: cfg,
    trades,
    orders,
    equityCurve,
    finalCash: cash,
    barsTested: bars.length - warmUp,
    firstBar: bars[warmUp] ? bars[warmUp].time : null,
    lastBar: bars[bars.length - 1].time,
  }
}

function positionValue(position, bar) {
  return position ? position.shares * bar.close : 0
}

function closeTrade(position, bar, exitPrice, exitFee, reason) {
  const gross = (exitPrice - position.entryPrice) * position.shares
  const fees = position.entryFee + exitFee
  const net = gross - fees
  return {
    symbol: position.symbol,
    shares: position.shares,
    entryTime: position.entryTime,
    entryPrice: position.entryPrice,
    entryReason: position.entryReason,
    exitTime: bar.time,
    exitPrice,
    exitReason: reason,
    barsHeld: position.barsHeld,
    grossPnl: gross,
    fees,
    pnl: net,
    returnPct: position.entryPrice > 0
      ? (net / (position.entryPrice * position.shares)) * 100
      : 0,
    // The full feature vector at entry, so any trade can be reconstructed and
    // audited long after the fact.
    entryFeatures: position.features,
  }
}

function emptyResult(symbol, strategy, params, config) {
  return {
    symbol,
    strategy: { id: strategy.id, name: strategy.name },
    params,
    config,
    trades: [],
    orders: [],
    equityCurve: [],
    finalCash: config.initialCash,
    barsTested: 0,
    firstBar: null,
    lastBar: null,
    note: "Not enough bars to test",
  }
}

/**
 * Run a strategy across many symbols and combine into one portfolio-level
 * result. Each symbol gets an equal slice of capital, which keeps the
 * comparison between strategies honest.
 */
export function backtestPortfolio({ symbols, barsBySymbol, strategy, params, config }) {
  const cfg = { ...DEFAULT_CONFIG, ...(config || {}) }
  const perSymbolCash = cfg.initialCash / Math.max(1, symbols.length)

  const results = symbols.map(symbol =>
    backtestSymbol({
      symbol,
      bars: barsBySymbol[symbol] || [],
      strategy,
      params,
      config: { ...cfg, initialCash: perSymbolCash },
    })
  )

  const allTrades = results.flatMap(r => r.trades)

  // Combine equity curves on the union of timestamps so the portfolio line is
  // not distorted by symbols whose histories start on different dates.
  const times = new Set()
  for (const r of results) for (const p of r.equityCurve) times.add(p.time)
  const sorted = [...times].sort((a, b) => a - b)

  const cursors = results.map(() => 0)
  const lastEquity = results.map(r => (r.equityCurve[0] ? r.equityCurve[0].equity : perSymbolCash))
  const curve = []
  for (const t of sorted) {
    let total = 0
    results.forEach((r, idx) => {
      while (cursors[idx] < r.equityCurve.length && r.equityCurve[cursors[idx]].time <= t) {
        lastEquity[idx] = r.equityCurve[cursors[idx]].equity
        cursors[idx] += 1
      }
      total += lastEquity[idx]
    })
    curve.push({ time: t, equity: total })
  }

  return {
    strategy: { id: strategy.id, name: strategy.name },
    params: { ...strategy.params, ...(params || {}) },
    config: cfg,
    symbols,
    perSymbol: results,
    trades: allTrades,
    equityCurve: curve,
  }
}
